styles.h1:
font-family:
  "Helvetica Neue", "YuGothic", "Hiragino Kaku Gothic ProN", sans-serif;
font-size: 30px;
position: relative;
color: #000;
margin: 25px 0 25px 0;
letter-spacing: -1px;
font-weight: 800;
text-align: left;
line-height: 1.1;
padding-left: 15px;
padding-bottom: 0;
border-left: 5px solid #ff0033;

styles.h2:
font-size: 18px;
color: #ff0033;
margin: 25px 0 15px 0;
font-weight: 700;
letter-spacing: 1px;
text-align: left;
position: relative;
display: inline-block;
padding: 0 5px;
background: #fff;
z-index: 2;

styles.h3:
display: block;
color: #000;
margin: 20px 0 10px 0;
font-size: 16px;
font-weight: 700;
letter-spacing: 0.5px;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.strong:
color: #000;
font-weight: 700;
background: linear-gradient(transparent 60%, rgba(255, 0, 51, 0.2) 40%);
padding: 0 2px;

styles.a:
color: #000;
text-decoration: none;
border-bottom: 1px solid #ff0033;
transition: all 0.2s ease;

styles.blockquote:
background-color: #fff;
border-left: 3px solid #ff0033;
color: #666;
padding: 15px 20px;
margin: 20px 0;
font-style: italic;
position: relative;

styles.pre:
border: 1px solid #eee;
background-color: #f9f9f9;
padding: 15px;
overflow-x: auto;
font-family: "SF Mono", monospace;
font-size: 14px;

styles.hr:
height: 3px;
border: none;
background: repeating-linear-gradient(
  90deg,
  #000,
  #000 5px,
  transparent 5px,
  transparent 10px
);
margin: 25px 0;

styles.img:
max-width: 100%;
height: auto;
margin: 20px 0;
border: 5px solid #fff;
box-shadow: 0 3px 10px rgba(0, 0, 0, 0.1);
transform: rotate(-1deg);

styles.th:
background-color: #000;
color: #fff;
padding: 10px;
text-align: left;
font-weight: 600;

font-size: 12px;
letter-spacing: 1px;
